func processAll(ctx context.Context, items []Item) error {
	var wg sync.WaitGroup
	errCh := make(chan error, len(items))
	for _, it := range items {
		wg.Add(1)
		go func(it Item) {
			defer wg.Done()
			if err := process(ctx, it); err != nil {
				errCh <- fmt.Errorf("process %v: %w", it.ID, err)
			}
		}(it)
	}
	wg.Wait()
	close(errCh)
	for err := range errCh {
		if err != nil {
			return err
		}
	}
	return nil
}
